function orderBySetBits(nums: number[]): number[] {
  const bits = (x: number) => {
    let c = 0;
    while (x) { x &= x - 1; c++; }
    return c;
  };
  return [...nums].sort((a, b) => bits(a) - bits(b) || a - b);
}

