class Solution:
    def orderBySetBits(self, nums: List[int]) -> List[int]:
        def bits(x: int) -> int:
            c = 0
            while x:
                x &= x - 1
                c += 1
            return c

        return sorted(nums, key=lambda v: (bits(v), v))

