function orderBySetBits(nums: number[]): number[] {
  const keyed = nums.map(v => {
    let c = 0, x = v;
    while (x) { c += x & 1; x >>= 1; }
    return c * 100000 + v;
  });
  keyed.sort((a, b) => a - b);
  return keyed.map(k => k % 100000);
}

